  "headline": "Protamine sulfate is not on FDA's current shortage list; the earlier shortage posted 2021-04-20 is resolved",
  "headline_cites": ["D7"],
  "sentences": [
    {
      "text": "FDA's records show protamine sulfate is not on the current shortage list as of 2026-10-21, and the earlier shortage first posted on 2021-04-20 has been resolved.",
      "cites": ["D7"]
    },
    {
      "text": "The product label for protamine sulfate 10 mg/mL 5 mL vial names Fresenius Kabi USA, LLC as the labeler and registered plant (FEI 1450022).",
      "cites": ["E11"]
    },
    {
      "text": "FDA inspection 1123748 at that plant ended 2020-05-18 and was classified OAI, with the classification letter dated 2024-05-22, which was 337 days before the shortage posting on 2021-04-20.",
      "cites": ["D3", "E8"]
    },
    {
      "text": "FDA inspection 1174894 at the same plant ended 2022-06-30 and was classified OAI, with the classification letter dated 2024-04-30, which was 436 days after the shortage posting on 2021-04-20.",
      "cites": ["D4", "E9"]
    },
    {
      "text": "The most recent inspection at the plant, FDA inspection 1216183, ended 2023-08-24 and was classified VAI.",
      "cites": ["E10"]
    },
    {
      "text": "Corvale East holds 293 vials with 31.1 days on hand at 9.4 vials per day, and Corvale General holds 160 vials with 14.9 days on hand at 10.7 vials per day.",
      "cites": ["D1", "D2"]
    }
  ]
}
